                                                                                <p>A antiga Igreja dos Homens Pretos foi erguida nos idos de 1700, sendo um marco da segregação
                                                                                    racial na história da antiga capital. Reconstruída pelos padres dominicanos, na década de 1920, a
                                                                                    atual Igreja do Rosário destoa do conjunto de edifícios da antiga capital por apresentar
                                                                                    características arquitetônicas diferentes; o edifício neogótico, com uma única torre centralizada e
                                                                                    que pode ser vista de toda a região, apresenta em seu interior um conjunto de afrescos
                                                                                    elaborados pelo padre italiano Frei Nazareno Confaloni. Em seu interior estão túmulos de alguns
                                                                                    bispos da igreja católica, que antigamente ali eram enterrados.</p>
                                                                            
                                                                              
