                                                                                <p>
                                                                                A poetisa Cora Coralina escreveu inúmeros poemas. Em 1965 publicou o seu primeiro
                                                                                            livro: Poemas dos becos de Goiás e estórias mais, porém, foi no ano de 1980 que
                                                                                            ficou conhecida em todo o Brasil, quando o poeta Carlos Drummond de Andrade leu
                                                                                            as suas poesias.
                                                                                            Nos cinco últimos anos de sua vida, a poetisa Cora Coralina teve o
                                                                                            reconhecimento de sua obra e foi bastante homenageada. Além do artigo escrito
                                                                                            por Carlos Drummond de Andrade, em 1980, que deu projeção à poesia da autora,
                                                                                            nesse mesmo ano, ela recebeu o Troféu Jaburu, concedido pelo governo de Goiás.
                                                    
                                                                                </p>
